/* Application routes, state and user workflows. Loaded as a classic script for file://. */
(function () {
  'use strict';
  const U=window.PhilUI, DB=window.PhilDB, R=window.PhilReports, SEED=window.PHILPEN_SEED;
  const {icon,escape:e,number:n,date:fmtDate,fullName,initials,button:btn,tag,empty,options,input,select,toast}=U;
  const MONTHS=['January','February','March','April','May','June','July','August','September','October','November','December'];
  const NAV=[['dashboard','Overview','dashboard'],['patients','Patient registry','people'],['assessments','Assessments','clipboard'],['medications','Medications','heart'],['reports','Reports & indicators','chart'],['equipment','Equipment','equipment'],['settings','Settings & backup','settings']];
  const MEDS=[['amlodipine5','Amlodipine · 5 mg'],['amlodipine10','Amlodipine · 10 mg'],['losartan50','Losartan · 50 mg'],['losartan100','Losartan · 100 mg'],['simvastatin','Simvastatin'],['atorvastatin','Atorvastatin'],['hydrochlorothiazide','Hydrochlorothiazide'],['metformin','Metformin · 500 mg'],['gliclazide','Gliclazide'],['insulinR','Insulin · R'],['insulinNPH','Insulin · NPH'],['insulin7030','Insulin · 70/30']];
  const RISKS=[['smoker','Current tobacco user'],['bingeDrinker','Binge drinking'],['inactive','Insufficient activity'],['unhealthyDiet','Unhealthy diet'],['overweight','Overweight'],['obese','Obesity']];
  const state={route:'dashboard',patients:[],assessments:[],equipment:[],audit:[],settings:{},filters:{year:new Date().getFullYear(),month:'all',barangay:'all'},query:'',condition:'all',sex:'all',page:1,sort:'name',assessmentScroll:0,ready:false};
  const main=document.getElementById('main'),modal=document.getElementById('modal');
  let modalDirty=false;

  const assessmentDate=a=>a&&a.datePrecision==='month'?MONTHS[Number(a.date.slice(5,7))-1]+' '+a.date.slice(0,4)+' (day not recorded)':fmtDate(a&&a.date);
  const brgyNames=()=>SEED.barangays.map(b=>b.name);
  const patientById=id=>state.patients.find(p=>p.id===id);
  const assessmentById=id=>state.assessments.find(a=>a.id===id);
  function latest(patientId){return state.assessments.filter(a=>a.patientId===patientId).sort((a,b)=>b.date.localeCompare(a.date)||b.id.localeCompare(a.id))[0];}
  function summary(filters){return R.summarize(state.patients,state.assessments,filters||state.filters);}
  function context(){return {patients:state.patients,assessments:state.assessments,equipment:state.equipment,settings:state.settings,barangays:SEED.barangays,filters:{...state.filters}};}
  function period(){return (state.filters.month==='all'?'Full year':MONTHS[Number(state.filters.month)-1])+' '+state.filters.year;}
  function scopedPopulation(){const b=SEED.barangays.find(b=>b.name===state.filters.barangay);return b?b.total:state.settings.eligiblePopulation;}
  function targetForSelection(){const b=SEED.barangays.find(b=>b.name===state.filters.barangay);const annual=b&&state.settings.targetRate===0.4?b.annual:Math.round(scopedPopulation()*state.settings.targetRate);return {annual,selected:state.filters.month==='all'?annual:Math.round(annual/12)};}
  function conditions(a){if(!a)return tag('Not assessed');return (a.hypertension?tag('Hypertension','amber')+' ':'')+(a.diabetes?tag('Diabetes','rose'):'')||tag('No HTN / DM recorded','green');}
  function identity(p){return '<div class="person-cell"><span class="person-avatar">'+e(initials(p))+'</span><div><button class="table-link" data-action="view-patient" data-id="'+e(p.id)+'">'+e(fullName(p))+'</button><div class="table-secondary">'+e(p.philhealth?'PH '+p.philhealth:'ID '+p.id.slice(-8).toUpperCase())+'</div></div></div>';}
  function iconBtn(action,name,title,id){return '<button class="icon-button" data-action="'+action+'" data-id="'+e(id)+'" title="'+e(title)+'" aria-label="'+e(title)+'">'+icon(name)+'</button>';}
  function heading(title,sub,actions){return '<div class="page-heading"><div><div class="eyebrow">'+e(state.settings.lgu||'BINANGONAN')+' COMMUNITY HEALTH</div><h1>'+title+'</h1><p>'+sub+'</p></div><div class="actions">'+(actions||'')+'</div></div>';}
  function filterBar(){return '<div class="filter-bar"><div class="filters"><label class="screen-reader-only" for="period-year">Reporting year</label><input class="year-input" id="period-year" data-filter="year" type="number" min="2000" max="2200" value="'+e(state.filters.year)+'" aria-label="Reporting year"><select data-filter="month" aria-label="Reporting month">'+options([['all','Full year'],...MONTHS.map((m,i)=>[String(i+1),m])],state.filters.month)+'</select><select data-filter="barangay" aria-label="Barangay filter">'+options([['all','All barangays'],...brgyNames()],state.filters.barangay)+'</select></div><div class="filter-caption">'+icon('filter')+e(period())+' · '+(state.filters.barangay==='all'?'40 barangays':e(state.filters.barangay))+'</div></div>';}
  function stat(label,value,detail,name,color){return '<div class="stat-card"><div class="stat-top"><span>'+label+'</span><span class="stat-icon '+(color||'')+'">'+icon(name)+'</span></div><div class="stat-number">'+n(value)+'</div><div class="stat-foot">'+detail+'</div></div>';}
  function pagination(total){const size=10,pages=Math.max(1,Math.ceil(total/size));state.page=Math.min(state.page,pages);return '<div class="pagination"><span>'+(total?'Showing '+n((state.page-1)*size+1)+'–'+n(Math.min(state.page*size,total))+' of '+n(total):'0 records')+'</span><div class="actions"><button class="page-tab" data-action="page" data-page="'+(state.page-1)+'" '+(state.page<=1?'disabled':'')+'>Previous</button><span class="page-tab selected">'+state.page+' / '+pages+'</span><button class="page-tab" data-action="page" data-page="'+(state.page+1)+'" '+(state.page>=pages?'disabled':'')+'>Next</button></div></div>';}
  function pageSlice(rows){state.page=Math.max(1,Math.min(state.page,Math.ceil(rows.length/10)||1));return rows.slice((state.page-1)*10,state.page*10);}

  async function refresh(){const values=await Promise.all(['patients','assessments','equipment','audit','settings'].map(s=>DB.all(s)));[state.patients,state.assessments,state.equipment,state.audit]=values;state.settings=values[4].find(x=>x.id==='main')||SEED.settings;state.audit.sort((a,b)=>b.at.localeCompare(a.at));document.getElementById('workspace-name').innerHTML=e(titleCase(state.settings.lgu))+'<small>Municipal health workspace</small>';document.getElementById('footer-year').textContent=new Date().getFullYear();}
  function titleCase(text){return String(text||'').toLowerCase().replace(/\b\w/g,c=>c.toUpperCase());}
  function route(){const key=location.hash.slice(1).split('?')[0];state.route=NAV.some(n=>n[0]===key)?key:'dashboard';state.assessmentScroll=0;state.page=1;state.query='';state.condition='all';state.sex='all';render();document.getElementById('sidebar').classList.remove('open');}
  function render(){if(!state.ready)return;document.getElementById('navigation').innerHTML=NAV.map(([key,label,ico])=>'<a href="#'+key+'" class="nav-link '+(state.route===key?'active':'')+'" '+(state.route===key?'aria-current="page"':'')+'>'+icon(ico)+'<span>'+label+'</span>'+(key==='patients'&&state.patients.length?'<span class="nav-count">'+n(state.patients.length)+'</span>':'')+'</a>').join('');document.getElementById('breadcrumb').textContent=NAV.find(n=>n[0]===state.route)[1];const pages={dashboard:dashboardPage,patients:patientsPage,assessments:assessmentsPage,reports:reportsPage,medications:medicationsPage,equipment:equipmentPage,settings:settingsPage};main.innerHTML=pages[state.route]();restoreAssessmentScroll();}

  function dashboardPage(){const s=summary(),yearSummary=summary({...state.filters,month:'all'}),t=targetForSelection(),pc=t.annual?100*yearSummary.screened/t.annual:0,max=Math.max(1,...s.monthly),recent=[...s.assessments].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,4);const due=state.patients.map(p=>({p,a:latest(p.id)})).filter(x=>x.a&&x.a.nextVisit&&x.a.nextVisit<=U.today()&&(state.filters.barangay==='all'||x.p.barangay===state.filters.barangay)).sort((a,b)=>a.a.nextVisit.localeCompare(b.a.nextVisit));
    return heading('Municipal overview','A clearer picture of your community’s screening and care.',btn('Export report','export-workbook','download')+btn('New assessment','new-assessment','plus','btn-primary'))+filterBar()+
      '<div class="stats-grid">'+stat('People screened',s.screened,'<strong>'+n(s.assessments.length)+'</strong> assessments in this period','people')+stat('Hypertension',s.hypertensive,'<strong>'+n(s.treatedHTN)+'</strong> with medication recorded','heart','amber')+stat('Type II diabetes',s.diabetic,'<strong>'+n(s.treatedDM)+'</strong> with medication recorded','drop','rose')+stat('Eligible population',scopedPopulation(),'Ages 20 and above · workbook baseline','target','blue')+'</div>'+
      '<div class="dashboard-grid"><section class="panel"><div class="panel-head"><div><h2>Screening activity</h2><p>People assessed each month · '+e(state.filters.year)+'</p></div>'+tag('12 months')+'</div><div class="chart-wrap"><div class="bar-chart" role="img" aria-label="Monthly screening counts: '+e(s.monthly.map((v,i)=>MONTHS[i]+' '+v).join(', '))+'">'+s.monthly.map((v,i)=>'<div class="bar-column" title="'+MONTHS[i]+': '+n(v)+'"><span class="bar-value">'+(v?n(v):'')+'</span><div class="bar '+(i===new Date().getMonth()?'active':'')+'" style="height:'+Math.max(1,v/max*85)+'%"></div></div>').join('')+'</div><div class="bar-labels">'+MONTHS.map(m=>'<span>'+m.slice(0,3)+'</span>').join('')+'</div></div><div class="chart-legend"><span class="legend-box"></span>Unique patients per month'+(!yearSummary.screened?' · No assessments recorded yet':'')+'</div></section>'+
      '<section class="panel target-panel"><div class="panel-head"><div><div class="eyebrow">REACHING YOUR COMMUNITY</div><h2 class="target-topline">'+icon('target')+' Annual screening target</h2><p>'+Math.round(state.settings.targetRate*100)+'% of eligible adults · '+state.filters.year+'</p></div></div><div class="target-core"><div class="progress-ring" style="--progress:'+Math.min(100,pc)+'%"><div class="progress-ring-inner"><strong>'+pc.toFixed(1)+'%</strong><small>OF ANNUAL TARGET</small></div></div><div class="target-values"><div><strong>'+n(yearSummary.screened)+'</strong><span>people screened</span></div><div><strong>'+n(t.annual)+'</strong><span>annual target</span></div></div></div><div class="target-footer">'+(t.annual?'<strong>'+n(Math.max(0,t.annual-yearSummary.screened))+' more people</strong> to reach the annual target.':'Set an eligible population and target in Settings.')+'</div></section></div>'+
      '<div class="dashboard-bottom"><section class="panel"><div class="panel-head"><div><h2>Recent assessments</h2><p>Your latest recorded visits</p></div><a class="pill-link" href="#assessments">View all →</a></div>'+(recent.length?'<div class="table-wrap"><table><thead><tr><th>Patient</th><th>Assessment</th><th>Recorded condition</th></tr></thead><tbody>'+recent.map(a=>{const p=patientById(a.patientId);return '<tr><td>'+identity(p)+'</td><td>'+assessmentDate(a)+'<div class="table-secondary">'+e(p.barangay)+'</div></td><td>'+conditions(a)+'</td></tr>';}).join('')+'</tbody></table></div>':empty('Your first assessment starts here','Register a patient, then record their PhilPEN assessment.',btn('Register a patient','new-patient','plus','btn-text'),'clipboard'))+'</section><section class="panel"><div class="panel-head"><div><h2>Recorded risk factors</h2><p>Latest assessment per person in this period</p></div><span class="stat-icon">'+icon('leaf')+'</span></div><div class="panel-body">'+RISKS.map(([k,l])=>'<div class="risk-row"><span class="risk-label">'+l+'</span><div class="risk-track"><div class="risk-fill" style="width:'+(s.screened?Math.min(100,(s.riskCounts[k]||0)/s.screened*100):0)+'%"></div></div><span class="risk-count">'+n(s.riskCounts[k])+'</span></div>').join('')+'<div class="risk-legend">A person may have more than one recorded risk factor.</div></div></section></div>'+
      (due.length?'<section class="panel section-gap"><div class="panel-head"><div><h2>Follow-ups due</h2><p>Based on the next visit date in each patient’s latest assessment</p></div>'+tag(due.length+' due','amber')+'</div><div class="panel-body">'+due.slice(0,5).map(({p,a})=>'<div class="followup-item"><span>'+e(fullName(p))+' <span class="muted">· '+e(p.barangay)+'</span></span><div class="actions">'+tag(fmtDate(a.nextVisit),'amber')+btn('Record visit','new-assessment','plus','btn-small','data-id="'+e(p.id)+'"')+'</div></div>').join('')+'</div></section>':'');
  }

  function patientRows(){let rows=state.patients.filter(p=>(state.filters.barangay==='all'||p.barangay===state.filters.barangay)&&(state.sex==='all'||p.sex===state.sex));if(state.query){const q=state.query.toLowerCase();rows=rows.filter(p=>[fullName(p),p.id,p.philhealth,p.phone,p.barangay].join(' ').toLowerCase().includes(q));}if(state.condition!=='all')rows=rows.filter(p=>{const a=latest(p.id);return state.condition==='unassessed'?!a:a&&a[state.condition];});return rows.sort((a,b)=>state.sort==='recent'?b.createdAt.localeCompare(a.createdAt):fullName(a).localeCompare(fullName(b)));}
  function patientTable(){const rows=patientRows(),slice=pageSlice(rows);return (rows.length?'<div class="table-wrap"><table><thead><tr><th>Patient</th><th>Sex / age</th><th>Barangay</th><th>Latest condition</th><th>Last assessed</th><th>Actions</th></tr></thead><tbody>'+slice.map(p=>{const a=latest(p.id),age=U.age(p.dob,U.today());return '<tr><td>'+identity(p)+'</td><td>'+e(p.sex==='M'?'Male':'Female')+'<div class="table-secondary">'+(age===null?'DOB not recorded':age+' years old')+'</div></td><td>'+e(p.barangay)+'</td><td>'+conditions(a)+'</td><td>'+assessmentDate(a)+'</td><td><div class="cell-actions">'+iconBtn('new-assessment','plus','Add assessment',p.id)+iconBtn('edit-patient','edit','Edit patient',p.id)+iconBtn('delete-patient','trash','Delete patient',p.id)+'</div></td></tr>';}).join('')+'</tbody></table></div>':empty(state.patients.length?'No matching patients':'Build your patient registry',state.patients.length?'Try a different name, barangay, or condition.':'Add a patient or import patient information from an Excel or CSV file.',state.patients.length?'':btn('Register a patient','new-patient','plus','btn-primary')))+pagination(rows.length);}
  function patientsPage(){return heading('Patient registry','Manage patient information and follow each person’s assessment history.',btn('Import Excel','import-excel','upload')+btn('Import CSV','import-csv','upload')+btn('Add patient','new-patient','plus','btn-primary'))+'<section class="panel"><div class="table-toolbar"><div class="search-box">'+icon('search')+'<input id="patient-search" class="search-field" type="search" value="'+e(state.query)+'" placeholder="Search name, PhilHealth, or phone…" aria-label="Search patients"></div><div class="filters"><select data-filter="barangay" aria-label="Barangay">'+options([['all','All barangays'],...brgyNames()],state.filters.barangay)+'</select><select id="condition-filter" aria-label="Condition">'+options([['all','All conditions'],['hypertension','Hypertension'],['diabetes','Type II diabetes'],['unassessed','Not assessed']],state.condition)+'</select><select id="sex-filter" aria-label="Sex">'+options([['all','All sexes'],['M','Male'],['F','Female']],state.sex)+'</select><select id="sort-filter" aria-label="Sort patients">'+options([['name','Name A–Z'],['recent','Newest first']],state.sort)+'</select></div></div><div id="patient-results">'+patientTable()+'</div></section><div class="actions section-gap">'+btn('Export patients CSV','patients-csv','download','btn-small')+btn('Download import template','csv-template','download','btn-text btn-small')+'<span class="small muted">'+n(state.patients.length)+' registered patients</span></div>';}

  function assessmentRows(){let rows=summary().assessments;if(state.query){const q=state.query.toLowerCase();rows=rows.filter(a=>fullName(patientById(a.patientId)).toLowerCase().includes(q));}return [...rows].sort((a,b)=>b.date.localeCompare(a.date)||b.id.localeCompare(a.id));}

  const ASSESSMENT_GROUPS=[['visit','Patient & visit'],['risks','Risk factors & BMI'],['conditions','HTN & diabetes'],['medicines','Medications'],['followup','Follow-up & notes']];
  function assessmentColumns(){
    const yn=value=>tag(value?'Yes':'No',value?'blue':'');
    const missing=()=>'<span class="muted">Not recorded</span>';
    const provided=(a,type)=>{const value=a[type==='HTN'?'htnMedicationProvided':'dmMedicationProvided'];return value==null?(R.treated(a,type)?yn(true)+'<div class="table-secondary">From source / medicines</div>':missing()):yn(value);};
    const source=(a,type,which)=>{const value=a[type==='HTN'?'htnSource':'dmSource'];return value?yn(R.treated(a,type)&&(value===which||value==='both')):missing();};
    const bmi=(a,category)=>a.bmiClass?yn(a.bmiClass===category):missing();
    return [
      {key:'sex',label:'Sex',group:'visit',cell:(a,p)=>e(p.sex==='M'?'Male':'Female')},
      {key:'barangay',label:'Barangay',group:'visit',cell:(a,p)=>e(p.barangay||'—')},
      {key:'date',label:'Assessed on',group:'visit',cell:a=>assessmentDate(a)},
      {key:'age',label:'Age at visit',group:'visit',cell:a=>e(a.age)+' years'},
      {key:'ageGroup',label:'Age group',group:'visit',cell:a=>a.age>=60?'60 years and above':'20–59 years'},
      {key:'dob',label:'Date of birth',group:'visit',cell:(a,p)=>fmtDate(p.dob)},
      {key:'address',label:'House / sitio / street',group:'visit',cell:(a,p)=>e(p.address||'—'),wide:true},
      {key:'philhealth',label:'PhilHealth number',group:'visit',cell:(a,p)=>e(p.philhealth||'—')},
      {key:'phone',label:'Contact number',group:'visit',cell:(a,p)=>e(p.phone||'—')},
      {key:'riskAssessed',label:'Risk assessed (PhilPEN)',group:'risks',cell:a=>yn(a.riskAssessed!==false)},
      ...RISKS.slice(0,4).map(([key,label])=>({key,label,group:'risks',cell:a=>yn(a[key])})),
      {key:'weight',label:'Weight (kg)',group:'risks',cell:a=>a.weightKg==null?'—':e(a.weightKg)},
      {key:'height',label:'Height (m)',group:'risks',cell:a=>a.heightM==null?'—':e(a.heightM)},
      {key:'bmi',label:'Calculated BMI',group:'risks',cell:a=>a.weightKg&&a.heightM?(a.weightKg/a.heightM**2).toFixed(1):'—'},
      {key:'bmiClass',label:'Recorded BMI category',group:'risks',cell:a=>a.bmiClass?e(titleCase(a.bmiClass)):missing()},
      {key:'overweight',label:'Overweight',group:'risks',cell:a=>bmi(a,'overweight')},
      {key:'obese',label:'Obese',group:'risks',cell:a=>bmi(a,'obese')},
      {key:'hypertension',label:'Hypertension',group:'conditions',cell:a=>yn(a.hypertension)},
      {key:'htnProvided',label:'Antihypertensive medication provided',group:'conditions',cell:a=>provided(a,'HTN')},
      {key:'htnFacility',label:'HTN · provided by facility',group:'conditions',cell:a=>source(a,'HTN','facility')},
      {key:'htnPocket',label:'HTN · out of pocket',group:'conditions',cell:a=>source(a,'HTN','out-of-pocket')},
      {key:'diabetes',label:'Type II diabetes',group:'conditions',cell:a=>yn(a.diabetes)},
      {key:'dmProvided',label:'Antidiabetic medication provided',group:'conditions',cell:a=>provided(a,'DM')},
      {key:'dmFacility',label:'DM · provided by facility',group:'conditions',cell:a=>source(a,'DM','facility')},
      {key:'dmPocket',label:'DM · out of pocket',group:'conditions',cell:a=>source(a,'DM','out-of-pocket')},
      ...MEDS.map(([key,label])=>({key,label,group:'medicines',cell:a=>R.frequency(a,key)>0?'<strong>'+R.frequency(a,key)+'× / day</strong>':missing()})),
      {key:'nextVisit',label:'Next visit',group:'followup',cell:a=>fmtDate(a.nextVisit)},
      {key:'remarks',label:'Remarks',group:'followup',cell:a=>e(a.remarks||'—'),wide:true}
    ];
  }
  function assessmentTable(){
    const rows=assessmentRows(),slice=pageSlice(rows),columns=assessmentColumns();
    if(!rows.length)return empty('No assessments in this period','Choose another reporting period or record a new assessment.',btn('New assessment','new-assessment','plus','btn-primary'),'clipboard')+pagination(0);
    return '<div class="assessment-column-tools"><div><strong>All '+(columns.length+2)+' columns</strong><span>Scroll sideways, or jump to a field group. Patient and actions stay visible.</span></div><div class="actions" aria-label="Jump to assessment columns">'+ASSESSMENT_GROUPS.map(([key,label])=>'<button class="btn btn-small" data-action="assessment-columns" data-group="'+key+'">'+e(label)+'</button>').join('')+'</div></div>'+
      '<div id="assessment-grid" class="table-wrap assessment-grid" role="region" aria-label="Complete assessment records. Scroll horizontally for all fields." tabindex="0"><table class="assessment-table"><caption class="screen-reader-only">All patient, visit, NCD indicator and medication fields. Each row is a saved assessment.</caption><thead><tr class="assessment-group-head"><th class="assessment-patient" scope="col" rowspan="2">Patient</th>'+ASSESSMENT_GROUPS.map(([key,label])=>'<th scope="colgroup" colspan="'+columns.filter(c=>c.group===key).length+'" data-column-group="'+key+'">'+e(label)+'</th>').join('')+'<th class="assessment-actions" scope="col" rowspan="2">Actions</th></tr><tr>'+columns.map(c=>'<th scope="col" data-field="'+c.key+'" class="'+(c.wide?'assessment-wide':'')+'">'+e(c.label)+'</th>').join('')+'</tr></thead><tbody>'+slice.map(a=>{const p=patientById(a.patientId);return '<tr><th scope="row" class="assessment-patient">'+identity(p)+'</th>'+columns.map(c=>'<td class="'+(c.wide?'assessment-wide':'')+'">'+c.cell(a,p)+'</td>').join('')+'<td class="assessment-actions"><div class="cell-actions">'+iconBtn('edit-assessment','edit','Edit assessment',a.id)+iconBtn('delete-assessment','trash','Delete assessment',a.id)+'</div></td></tr>';}).join('')+'</tbody></table></div>'+pagination(rows.length);
  }
  function restoreAssessmentScroll(){const grid=document.getElementById('assessment-grid');if(grid)grid.scrollLeft=state.assessmentScroll;}
  function refreshAssessmentTable(){document.getElementById('assessment-results').innerHTML=assessmentTable();restoreAssessmentScroll();}
  document.addEventListener('scroll',event=>{if(event.target.id==='assessment-grid')state.assessmentScroll=event.target.scrollLeft;},true);
  function jumpAssessmentColumns(group){
    const grid=document.getElementById('assessment-grid');if(!grid)return;
    const target=grid.querySelector('[data-column-group="'+group+'"]');if(!target)return;
    const pinned=grid.querySelector('.assessment-patient').getBoundingClientRect().width;
    grid.scrollTo({left:Math.max(0,grid.scrollLeft+target.getBoundingClientRect().left-grid.getBoundingClientRect().left-pinned),behavior:'instant'});
    grid.focus({preventScroll:true});
  }
  function assessmentsPage(){return heading('Assessment records','View all recorded patient, NCD indicator and medication fields for each visit.',btn('Export encounters','encounters-csv','download')+btn('New assessment','new-assessment','plus','btn-primary'))+filterBar()+'<section class="panel"><div class="table-toolbar"><div class="search-box">'+icon('search')+'<input id="assessment-search" class="search-field" type="search" placeholder="Search patient name…" value="'+e(state.query)+'" aria-label="Search assessment patients"></div><span class="tag">'+n(summary().assessments.length)+' visits in period</span></div><div id="assessment-results">'+assessmentTable()+'</div></section><p class="help-line">Each row is a visit. Edit a row using its pencil button. Medication columns show recorded frequency per day; “Not recorded” is different from an explicit No. Summary indicators use each patient’s latest assessment within the selected period.</p>';}



  function renderIndicatorPreview(form){
    const p=patientById(form.elements.patientId.value),a={bmiClass:form.elements.bmiClass.value,medications:{},htnSource:form.elements.htnSource.value,dmSource:form.elements.dmSource.value};
    for(const k of ['riskAssessed','smoker','bingeDrinker','inactive','unhealthyDiet','hypertension','diabetes'])a[k]=form.elements[k].checked;
    for(const k of ['htnMedicationProvided','dmMedicationProvided'])a[k]=form.elements[k].value===''?null:form.elements[k].value==='yes';
    for(const [k] of MEDS)a.medications[k]=Number(form.elements['med_'+k].value);
    const flags=R.metricFlags(a),age=Number(form.elements.age.value);
    document.getElementById('indicator-preview').innerHTML='<p><strong>'+e(p?(p.sex==='M'?'Male':'Female')+' · '+(age>=60?'60 years and above':age>=20?'20–59 years':'Age not eligible'):'Select a patient')+'</strong></p><div class="check-grid">'+R.indicatorLabels.map((label,i)=>'<div class="check-option"><span aria-label="'+(flags[i]?'Included':'Not included')+'">'+(flags[i]?'☑':'☐')+'</span> '+e(label)+'</div>').join('')+'</div>';
  }
  function indicatorSummaryTable(){const people=summary().people;return '<section class="panel section-gap"><div class="panel-head"><div><h2>All NCD indicators</h2><p>Latest assessment per person in the selected period · workbook age and sex groups</p></div></div><div class="table-wrap"><table><thead><tr><th>Indicator</th><th>Male 20–59</th><th>Female 20–59</th><th>Male 60+</th><th>Female 60+</th><th>Total</th></tr></thead><tbody>'+R.indicatorLabels.map((label,i)=>{const counts=[0,0,0,0];for(const a of people)if(R.metricFlags(a)[i])counts[(a.age>=60?2:0)+(a.patient.sex==='F'?1:0)]++;return '<tr><td>'+e(label)+'</td>'+counts.map(v=>'<td>'+n(v)+'</td>').join('')+'<td><strong>'+n(counts.reduce((a,b)=>a+b,0))+'</strong></td></tr>';}).join('')+'</tbody></table></div></section>';}
  function medicationsPage(){const s=summary(),rows=[...s.people].sort((a,b)=>fullName(a.patient).localeCompare(fullName(b.patient))),visible=pageSlice(rows);return heading('NCD medications','Record medications taken and medication access for each patient visit.',btn('Export Excel','export-workbook','download')+btn('Record medication','new-assessment','plus','btn-primary'))+filterBar()+'<section class="panel"><div class="panel-head"><div><h2>Workbook medication fields</h2><p>Latest visit per patient · summed recorded frequency/day, not stock quantity</p></div></div><div class="panel-body"><div class="field-grid three">'+MEDS.map(([k,label])=>'<div class="data-action"><div><h3>'+e(label)+'</h3><p>'+n(rows.filter(a=>R.frequency(a,k)>0).length)+' patients recorded</p></div><strong>'+n(rows.reduce((total,a)=>total+R.frequency(a,k),0))+'</strong></div>').join('')+'</div></div></section><section class="panel section-gap"><div class="panel-head"><div><h2>Patient medication records</h2><p>'+s.treatedHTN+' provided antihypertensives · '+s.treatedDM+' provided antidiabetics</p></div></div><div class="table-wrap"><table><thead><tr><th>Patient</th><th>Visit</th><th>Medications taken</th><th>Medication access</th><th>Action</th></tr></thead><tbody>'+visible.map(a=>'<tr><td>'+identity(a.patient)+'</td><td>'+assessmentDate(a)+'</td><td>'+MEDS.filter(([k])=>R.frequency(a,k)>0).map(([k,label])=>e(label)+' · '+R.frequency(a,k)+'×/day').join('<br>')+(MEDS.some(([k])=>R.frequency(a,k)>0)?'':'Not recorded')+'</td><td>HTN: '+(R.treated(a,'HTN')?'Provided':'Not recorded / not provided')+'<br>DM: '+(R.treated(a,'DM')?'Provided':'Not recorded / not provided')+'</td><td>'+btn('Edit medication','edit-assessment','edit','btn-small','data-id="'+e(a.id)+'"')+'</td></tr>').join('')+'</tbody></table></div>'+(!rows.length?empty('No medication records in this period','Select another period or record a patient assessment.',''):'')+pagination(rows.length)+'</section>';}

  function reportsPage(){const s=summary(),groups=s.byGroup;const rows=SEED.barangays.filter(b=>state.filters.barangay==='all'||b.name===state.filters.barangay).map(b=>{const counts=s.byBarangay.find(x=>x.name===b.name)||{screened:0,hypertensive:0,diabetic:0};return {...b,...counts};});return heading('Reports & indicators','Turn your recorded assessments into municipal reports.',btn('Print summary','print','print')+btn('Download Excel','export-workbook','download','btn-primary'))+filterBar()+indicatorSummaryTable()+'<div class="print-only">'+e(state.settings.facility)+' · '+e(period())+' · '+e(state.filters.barangay==='all'?'All barangays':state.filters.barangay)+'</div><section class="panel"><div class="panel-head"><div><h2>Screening by age & sex</h2><p>Unique people in '+e(period())+' · latest assessment per person</p></div>'+tag(n(s.screened)+' people','green')+'</div><div class="panel-body"><div class="report-summary">'+[['Adults · male',groups.adultMale],['Adults · female',groups.adultFemale],['Seniors · male',groups.seniorMale],['Seniors · female',groups.seniorFemale]].map(([l,v])=>'<div><strong>'+n(v)+'</strong><small>'+l+'</small><small>'+(l.startsWith('Adults')?'20–59 years':'60 years and above')+'</small></div>').join('')+'</div></div></section><div class="split-grid section-gap no-print"><section class="panel report-tile"><span class="stat-icon">'+icon('chart')+'</span><h2>NCD reporting workbook</h2><p>Download age and sex indicators, medication frequency totals, and a patient register aligned with the supplied PhilPEN column layout. The workbook also includes all visits and calculation notes.</p>'+btn('Export Excel workbook','export-workbook','download','btn-small')+'</section><section class="panel report-tile"><span class="stat-icon blue">'+icon('clipboard')+'</span><h2>Tabular extracts</h2><p>Export indicators for analysis, or all assessment visits in the selected period. CSV files open in Excel and preserve the distinction between patients and visits.</p><div class="actions">'+btn('Indicators CSV','indicators-csv','download','btn-small')+btn('Visits CSV','encounters-csv','download','btn-small')+'</div></section></div><section class="panel section-gap"><div class="panel-head"><div><h2>Barangay screening coverage</h2><p>Screened in selected period versus annual target</p></div><span class="tag">'+rows.length+' barangays</span></div><div class="table-wrap"><table><thead><tr><th>Barangay</th><th>Eligible adults</th><th>Annual target</th><th>Screened</th><th>Hypertension</th><th>Diabetes</th><th>Annual target reached</th></tr></thead><tbody>'+rows.map(b=>{const target=state.settings.targetRate===0.4?b.annual:Math.round(b.total*state.settings.targetRate);const pc=target?b.screened/target*100:null;return '<tr><td><span class="table-primary">'+e(b.name)+'</span></td><td>'+n(b.total)+'</td><td>'+n(target)+'</td><td>'+n(b.screened)+'</td><td>'+n(b.hypertensive)+'</td><td>'+n(b.diabetic)+'</td><td>'+(pc===null?'—':pc.toFixed(1)+'%')+'<div class="bar-mini"><span style="width:'+Math.min(100,pc||0)+'%"></span></div></td></tr>';}).join('')+'</tbody></table></div></section><p class="help-line">Source baseline: 40 barangays in the supplied workbook. The municipal target uses the eligible population in Settings; barangay populations retain the workbook baseline. Overlapping medication sources may count in both source columns.</p>';}

  function equipmentPage(){const totals=state.equipment.reduce((a,r)=>{for(const k of ['manualBP','automaticBP','glucometers','testStrips'])a[k]+=r[k]||0;return a;},{manualBP:0,automaticBP:0,glucometers:0,testStrips:0});const rows=SEED.barangays.filter(b=>!state.query||b.name.toLowerCase().includes(state.query.toLowerCase()));return heading('Equipment inventory','Keep a current count of screening equipment in each barangay.',btn('Update inventory','edit-equipment','plus','btn-primary'))+'<div class="stats-grid">'+stat('Manual BP apparatus',totals.manualBP,'Across recorded barangays','equipment')+stat('Automatic BP apparatus',totals.automaticBP,'Across recorded barangays','heart','blue')+stat('Glucometers',totals.glucometers,'Across recorded barangays','drop','amber')+stat('Glucose test strips',totals.testStrips,'Current recorded stock','equipment','rose')+'</div><div class="notice">'+icon('info')+'<span>'+state.equipment.length+' of 40 barangays have a saved inventory. A dash means no inventory has been recorded; a saved zero means none available.</span></div><section class="panel"><div class="table-toolbar"><h2>Barangay inventory</h2><div class="search-box">'+icon('search')+'<input id="equipment-search" class="search-field" type="search" placeholder="Search barangay…" aria-label="Search equipment barangay" value="'+e(state.query)+'"></div></div><div class="table-wrap"><table><thead><tr><th>Barangay</th><th>Manual BP</th><th>Automatic BP</th><th>Glucometers</th><th>Test strips</th><th>Last updated</th><th></th></tr></thead><tbody>'+rows.map(b=>{const r=state.equipment.find(r=>r.id===b.name);return '<tr><td class="table-primary">'+e(b.name)+'</td>'+['manualBP','automaticBP','glucometers','testStrips'].map(k=>'<td>'+(r?n(r[k]):'<span class="muted">—</span>')+'</td>').join('')+'<td>'+fmtDate(r&&r.updatedAt)+'</td><td>'+iconBtn('edit-equipment','edit','Edit '+b.name+' inventory',b.name)+'</td></tr>';}).join('')+'</tbody></table></div></section>';}

  function settingsPage(){const s=state.settings;return heading('Settings & backup','Manage reporting details and keep a portable copy of your records.','')+'<div class="settings-grid"><section class="panel"><div class="panel-head"><div><h2>Municipal & facility details</h2><p>These details appear in your exported reports.</p></div></div><div class="panel-body"><form id="settings-form"><div class="form-error" role="alert"></div><div class="field-grid">'+input('province','Province',s.province,'text','required maxlength="160"')+input('lgu','Municipality / LGU',s.lgu,'text','required maxlength="160"')+input('facility','Reporting facility',s.facility,'text','required maxlength="200"',true)+input('address','Facility address',s.address,'text','maxlength="500"',true)+input('eligiblePopulation','Eligible population · age 20+',s.eligiblePopulation,'number','required min="0" max="1000000000" step="1"')+input('targetRate','Annual screening target (%)',+(s.targetRate*100).toFixed(4),'number','required min="0" max="100" step="0.01"')+input('contactName','Contact person',s.contactName,'text','maxlength="160"',true)+input('contactPhone','Contact number',s.contactPhone,'tel','maxlength="60"')+input('viber','Viber number',s.viber,'tel','maxlength="60"')+input('email','Email address',s.email,'email','maxlength="254"')+'</div><div class="form-actions"><button class="btn btn-primary" type="submit">'+icon('check')+' Save settings</button></div></form></div></section><div><section class="panel"><div class="panel-head"><div><h2>Your local database</h2><p>'+n(state.patients.length)+' patients · '+n(state.assessments.length)+' assessments</p></div><span class="stat-icon">'+icon('database')+'</span></div><div class="panel-body"><div class="data-action"><div><h3>Download a full backup</h3><p>Patients, visits, equipment, settings and history.</p></div>'+btn('Back up','backup','download','btn-small')+'</div><div class="data-action"><div><h3>Restore a backup</h3><p>Validate a PhilPEN JSON backup before restoring.</p></div>'+btn('Restore','restore','upload','btn-small')+'</div><div class="data-action"><div><h3>Patient CSV template</h3><p>Use the template to import patient details.</p></div>'+btn('Template','csv-template','download','btn-small')+'</div><div class="data-action"><div><h3>Import Excel masterlist</h3><p>Preview patients, assessments and source notes from .xlsx or .xls.</p></div>'+btn('Import Excel','import-excel','upload','btn-small')+'</div><p><a class="source-download" href="data/TAGPOS-SEPTEMBER-RISK-PEN-MASTERLIST-2026.xlsx" download>Download supplied Tagpos masterlist ↗</a></p><p class="help-line">Records stay in this browser on this device. Use the same browser and keep the app in the same folder. Back up regularly; clearing browser data may remove local records. Backups contain personal health information.</p></div></section><section class="panel section-gap"><div class="panel-head"><div><h2>Recent activity</h2><p>Changes recorded by this workspace</p></div></div><div class="panel-body audit-list">'+(state.audit.length?state.audit.slice(0,12).map(a=>'<div class="audit-item"><strong>'+e(titleCase(a.action))+'</strong> · '+e(a.store)+'<small>'+e(a.detail||a.recordId)+'<br>'+fmtDate(a.at)+' '+new Date(a.at).toLocaleTimeString('en-PH',{hour:'2-digit',minute:'2-digit'})+'</small></div>').join(''):'<p class="small muted">No recorded changes yet.</p>')+'</div></section></div></div><section class="panel section-gap"><div class="panel-head"><div><h2>About this workspace</h2></div>'+tag('Offline · v1.0','green')+'</div><div class="panel-body"><ul class="source-list"><li>Based on the supplied PhilPEN workbook: municipal information, NCD indicators, medications, patient reporting form and Legend.</li><li>Includes 40 barangay baselines and the supplied 404 Tagpos patient records for September 2026. Starter records are added once per browser database. Existing records are retained.</li><li>Age is recorded at the assessment date. BMI and its category follow the supplied workbook when measurements are complete; otherwise the encoder can record a category. Diagnoses and medications are entered from the assessment.</li><li>This is a browser-local workspace. It has no shared server, account login or synchronization across devices.</li></ul></div></section>';}

  function showModal(title,subtitle,body){modalDirty=false;document.getElementById('modal-content').innerHTML='<div class="modal-header"><div><h2 id="modal-title">'+e(title)+'</h2>'+(subtitle?'<p>'+e(subtitle)+'</p>':'')+'</div><button type="button" class="icon-button" data-action="close-modal" aria-label="Close dialog">'+icon('close')+'</button></div><div class="modal-body">'+body+'</div>';if(!modal.open)modal.showModal();setTimeout(()=>{const focus=modal.querySelector('input:not([readonly]),select,button.btn');if(focus)focus.focus();},30);}
  function closeModal(force){if(!force&&modalDirty&&!window.confirm('Discard the unsaved changes in this form?'))return;modalDirty=false;modal.close();}
  function formFooter(label){return '<div class="form-actions"><button type="button" class="btn" data-action="close-modal">Cancel</button><button type="submit" class="btn btn-primary">'+icon('check')+label+'</button></div>';}
  function section(num,title,html){return '<section class="form-section"><div class="form-section-title"><span class="step-badge">'+num+'</span><h3>'+title+'</h3></div>'+html+'</section>';}
  function openPatient(id){const p=id?patientById(id):{};showModal(id?'Edit patient':'Register a patient','Fields marked * are required. Assessment details are recorded separately.','<form id="patient-form" data-id="'+e(id||'')+'"><div class="form-error" role="alert"></div>'+section('01','Personal information','<div class="field-grid">'+input('lastName','Family name',p.lastName,'text','required maxlength="100" autocomplete="family-name"')+input('firstName','First name',p.firstName,'text','required maxlength="100" autocomplete="given-name"')+input('middleName','Middle name',p.middleName,'text','maxlength="100"')+input('suffix','Suffix',p.suffix,'text','maxlength="30" placeholder="e.g. Jr., III"')+select('sex','Sex',[['M','Male'],['F','Female']],p.sex,'Select sex','required')+input('dob','Date of birth',p.dob,'date','min="1900-01-01" max="'+U.today()+'"')+'</div><p class="help-line">If birth date is unavailable, leave it blank and enter age when recording the assessment.</p>')+section('02','Location & contact','<div class="field-grid">'+select('barangay','Barangay',brgyNames(),p.barangay||(state.filters.barangay==='all'?'':state.filters.barangay),'Select barangay','required')+input('phone','Contact number',p.phone,'tel','maxlength="60"')+input('address','House no. / sitio / street',p.address,'text','maxlength="500"',true)+input('philhealth','PhilHealth number',p.philhealth,'text','maxlength="60" inputmode="numeric"',true)+'</div>')+formFooter(id?'Save changes':'Register patient')+'</form>');}
  function check(name,label,checked){return '<label class="check-option"><input type="checkbox" name="'+name+'" '+(checked?'checked':'')+'>'+label+'</label>';}
  function openAssessment(id,patientId){if(!state.patients.length){toast('Register a patient before recording an assessment.');openPatient();return;}const a=id?assessmentById(id):{},p=patientById(patientId||a.patientId),d=a.date||U.today();const patientOptions=[...state.patients].sort((a,b)=>fullName(a).localeCompare(fullName(b))).map(p=>[p.id,fullName(p)+' · '+p.barangay]);const age=p&&p.dob?U.age(p.dob,d):a.age;showModal(id?'Edit assessment':'New PhilPEN assessment','Record findings from the completed assessment. Medication entries are not prescriptions.','<form id="assessment-form" data-id="'+e(id||'')+'"><div class="form-error" role="alert"></div>'+section('01','Patient & visit','<div class="field-grid">'+select('patientId','Patient',patientOptions,p&&p.id,'Choose a patient','required')+input('date','Assessment date',d,'date','required min="2000-01-01" max="'+U.today()+'"')+select('datePrecision','Date precision',[['day','Exact day recorded'],['month','Reporting month only']],a.datePrecision||'day')+input('age','Age at assessment',age,'number','required min="20" max="120" step="1" '+(p&&p.dob?'readonly':''))+input('nextVisit','Next visit (optional)',a.nextVisit,'date','min="'+d+'"')+'</div><p class="help-line" id="age-help">'+(p&&p.dob?'Age is calculated from birth date on the assessment date.':'PhilPEN reporting covers ages 20 and above. Enter age if the birth date is unavailable.')+'</p>')+section('02','NCD indicators · risk assessment','<div class="check-grid">'+check('riskAssessed','Risk assessed using the PhilPEN protocol',a.riskAssessed!==false)+'</div><p class="help-line">Age and sex reporting groups are derived from the selected patient and assessment age.</p><div class="check-grid">'+RISKS.slice(0,4).map(([k,l])=>check(k,l,a[k])).join('')+'</div><div class="field-grid three section-gap">'+input('weightKg','Weight (kg)',a.weightKg,'number','min="10" max="500" step="0.1"')+input('heightM','Height (metres)',a.heightM,'number','min="0.5" max="2.75" step="0.01" placeholder="e.g. 1.65"')+input('bmi','Calculated BMI',a.weightKg&&a.heightM?(a.weightKg/a.heightM**2).toFixed(1):'','text','readonly placeholder="Enter height & weight"')+'</div><div class="field-grid section-gap">'+select('bmiClass','Recorded BMI category',[['','Not recorded'],['underweight','Underweight'],['normal','Normal'],['overweight','Overweight'],['obese','Obese']],a.bmiClass)+'</div><p class="help-line" id="bmi-help">Select the category recorded during assessment. BMI is weight ÷ height².</p>')+section('03','NCD indicators · conditions & treatment','<div class="check-grid">'+check('hypertension','Identified with hypertension',a.hypertension)+check('diabetes','Identified with Type II diabetes',a.diabetes)+'</div><div class="field-grid section-gap">'+select('htnMedicationProvided','Provided with antihypertensive medication',[['','Use existing source / medicines'],['yes','Yes — provided'],['no','No — not provided']],a.htnMedicationProvided==null?'':a.htnMedicationProvided?'yes':'no')+select('dmMedicationProvided','Provided with antidiabetic medication',[['','Use existing source / medicines'],['yes','Yes — provided'],['no','No — not provided']],a.dmMedicationProvided==null?'':a.dmMedicationProvided?'yes':'no')+select('htnSource','Hypertension medication source',[['','Not recorded'],['facility','Provided by facility'],['out-of-pocket','Out of pocket'],['both','Both sources']],a.htnSource)+select('dmSource','Diabetes medication source',[['','Not recorded'],['facility','Provided by facility'],['out-of-pocket','Out of pocket'],['both','Both sources']],a.dmSource)+'</div>')+section('04','NCD medication · all workbook fields','<div class="notice">'+icon('info')+'<span>Record frequency as entered in the workbook: 1, 2 or 3 times per day. These totals represent recorded daily frequency, not medicine inventory or dispensing quantity.</span></div><div class="field-grid three medication-grid">'+MEDS.map(([k,l])=>select('med_'+k,l,[[0,'Not recorded'],[1,'1 × per day'],[2,'2 × per day'],[3,'3 × per day']],a.medications&&a.medications[k]||0)).join('')+'</div>')+'<section class="form-section"><h3>NCD indicator preview</h3><p class="help-line">These are the indicator columns for this visit. A check means this record contributes 1 to the matching age and sex group.</p><div id="indicator-preview"></div></section>'+section('05','Remarks','<div class="field"><label for="f-remarks">Assessment notes</label><textarea id="f-remarks" name="remarks" rows="3" maxlength="5000" placeholder="Other findings or follow-up notes…">'+e(a.remarks)+'</textarea></div>')+formFooter(id?'Save changes':'Save assessment')+'</form>');updateAssessmentFields();}
  function updateAssessmentFields(changed){const f=modal.querySelector('#assessment-form');if(!f)return;const p=patientById(f.elements.patientId.value),d=f.elements.date.value;const saved=f.dataset.id&&assessmentById(f.dataset.id);const keepSource=saved&&saved.patientId===f.elements.patientId.value&&saved.date===d;if(!changed||['patientId','date'].includes(changed)){if(keepSource){f.elements.age.value=saved.age;f.elements.age.readOnly=false;document.getElementById('age-help').textContent='Recorded assessment age retained. Review source notes before changing it.';}else if(p&&p.dob&&d){f.elements.age.value=U.age(p.dob,d);f.elements.age.readOnly=true;document.getElementById('age-help').textContent='Age is calculated from birth date on the assessment date.';}else{f.elements.age.readOnly=false;document.getElementById('age-help').textContent='Enter the patient’s age at this assessment (20 years or above).';}}f.elements.nextVisit.min=d;const w=Number(f.elements.weightKg.value),h=Number(f.elements.heightM.value);f.elements.bmi.value=w&&h?(w/h**2).toFixed(1):'';const measured=Boolean(w&&h); f.elements.bmiClass.disabled=measured; if(measured && !(saved && Number(saved.weightKg)===w && Number(saved.heightM)===h && saved.bmiClass)) {const bmi=w/h**2; f.elements.bmiClass.value=bmi<18.5?'underweight':bmi<23?'normal':bmi<25?'overweight':'obese';} document.getElementById('bmi-help').textContent=measured?'Category follows the supplied workbook: underweight <18.5; normal <23; overweight <25; obese ≥25.':'Select the category recorded during assessment if complete measurements are unavailable.';renderIndicatorPreview(f);}
  function openEquipment(name){const r=state.equipment.find(r=>r.id===name)||{};showModal('Update equipment inventory','Enter the current count. A saved zero means none available.','<form id="equipment-form"><div class="form-error" role="alert"></div><div class="field-grid">'+select('equipmentBarangay','Barangay',brgyNames(),name,'Choose barangay','required')+input('manualBP','Manual BP apparatus',r.manualBP,'number','required min="0" max="1000000000" step="1"')+input('automaticBP','Automatic BP apparatus',r.automaticBP,'number','required min="0" max="1000000000" step="1"')+input('glucometers','Glucometers',r.glucometers,'number','required min="0" max="1000000000" step="1"')+input('testStrips','Glucose test strips',r.testStrips,'number','required min="0" max="1000000000" step="1"')+'</div>'+formFooter('Save inventory')+'</form>');}
  function viewPatient(id){const p=patientById(id);if(!p)return;const visits=state.assessments.filter(a=>a.patientId===id).sort((a,b)=>b.date.localeCompare(a.date));showModal('Patient record','Registry information and complete assessment history.','<div class="detail-summary"><span class="person-avatar">'+e(initials(p))+'</span><div><h2>'+e(fullName(p))+'</h2><p class="help-line">'+e(p.id)+'</p></div></div><dl class="detail-grid">'+[['Sex',p.sex==='M'?'Male':'Female'],['Birth date',fmtDate(p.dob)],['Barangay',p.barangay],['Address',p.address||'—'],['PhilHealth',p.philhealth||'—'],['Contact',p.phone||'—']].map(([k,v])=>'<div><dt>'+k+'</dt><dd>'+e(v)+'</dd></div>').join('')+'</dl><div class="actions">'+btn('Edit details','edit-patient','edit','btn-small','data-id="'+e(id)+'"')+btn('New assessment','new-assessment','plus','btn-primary btn-small','data-id="'+e(id)+'"')+'</div><div class="form-section section-gap"><h3>Assessment history <span class="muted">('+visits.length+')</span></h3>'+(!visits.length?'<p class="help-line">No assessments recorded for this patient.</p>':visits.map(a=>'<article class="detail-visit"><div class="detail-visit-head"><strong>'+assessmentDate(a)+'</strong>'+iconBtn('edit-assessment','edit','Edit assessment',a.id)+'</div>'+conditions(a)+'<p>Risk assessed: '+(a.riskAssessed===false?'No':'Yes')+' · HTN medication provided: '+(R.treated(a,'HTN')?'Yes':'No / not recorded')+' · DM medication provided: '+(R.treated(a,'DM')?'Yes':'No / not recorded')+'</p><p>'+MEDS.filter(([k])=>R.frequency(a,k)>0).map(([k,label])=>e(label)+' '+R.frequency(a,k)+'×/day').join('; ')+'</p><p>Age '+a.age+' · BMI '+(a.weightKg&&a.heightM?(a.weightKg/a.heightM**2).toFixed(1):'not recorded')+' · '+e(a.bmiClass||'Category not recorded')+'</p>'+(a.nextVisit?'<p>Next visit: '+fmtDate(a.nextVisit)+'</p>':'')+'<p>'+e(a.remarks||'No remarks.')+'</p></article>').join(''))+'</div>');}

  async function saveForm(form){const submit=form.querySelector('[type=submit]'),error=form.querySelector('.form-error');error.textContent='';if(!form.reportValidity())return;submit.disabled=true;try{const data=Object.fromEntries(new FormData(form)),id=form.dataset.id;let message='Changes saved.';if(form.id==='patient-form'){if(!brgyNames().includes(data.barangay))throw new Error('Choose a barangay from the list.');const old=id?patientById(id):{};const duplicate=state.patients.find(p=>p.id!==id&&p.firstName.toLowerCase()===data.firstName.trim().toLowerCase()&&p.lastName.toLowerCase()===data.lastName.trim().toLowerCase()&&p.dob===data.dob&&p.sex===data.sex&&p.barangay===data.barangay);if(duplicate&&!window.confirm('A patient with the same name, sex, birth date and barangay already exists. Save as a separate patient?'))return;await DB.put('patients',{...old,...data,...(id?{id}:{}),updatedAt:new Date().toISOString()});message=id?'Patient details updated.':'Patient registered. You can now add an assessment.';}else if(form.id==='assessment-form'){const p=patientById(data.patientId);if(!p)throw new Error('Choose a registered patient.');if(data.date>U.today())throw new Error('Assessment date cannot be in the future.');const row={...data,...(id?{id}:{}),datePrecision:data.datePrecision||'day',age:Number(data.age),weightKg:data.weightKg?Number(data.weightKg):null,heightM:data.heightM?Number(data.heightM):null,medications:{}};row.bmiClass=form.elements.bmiClass.value;for(const key of ['riskAssessed','smoker','bingeDrinker','inactive','unhealthyDiet','hypertension','diabetes'])row[key]=form.elements[key].checked;for(const key of ['htnMedicationProvided','dmMedicationProvided'])row[key]=data[key]===''?null:data[key]==='yes';for(const [key] of MEDS)row.medications[key]=Number(data['med_'+key]);if(row.htnSource&&!row.hypertension)throw new Error('Select hypertension before recording its medication source.');if(row.dmSource&&!row.diabetes)throw new Error('Select diabetes before recording its medication source.');const duplicate=state.assessments.find(a=>a.id!==id&&a.patientId===p.id&&a.date===row.date);if(duplicate)throw new Error('This patient already has an assessment on this date. Edit that visit instead.');await DB.put('assessments',row);message='Assessment saved. Reports have been updated.';}else if(form.id==='equipment-form'){await DB.put('equipment',{...data,id:data.equipmentBarangay,manualBP:Number(data.manualBP),automaticBP:Number(data.automaticBP),glucometers:Number(data.glucometers),testStrips:Number(data.testStrips),updatedAt:new Date().toISOString()});message='Equipment inventory saved.';}else if(form.id==='settings-form'){await DB.put('settings',{...data,id:'main',eligiblePopulation:Number(data.eligiblePopulation),targetRate:Number(data.targetRate)/100});message='Settings saved.';}await refresh();if(form.id!=='settings-form')closeModal(true);render();toast(message);}catch(err){error.textContent=err.message||'Unable to save. Please try again.';}finally{submit.disabled=false;}}

  function confirmDelete(kind,id){const patient=kind==='patients'?patientById(id):patientById(assessmentById(id).patientId);const visits=state.assessments.filter(a=>a.patientId===id).length;showModal(kind==='patients'?'Delete this patient?':'Delete this assessment?','This removes the saved record from the local database.','<p class="confirm-text">'+(kind==='patients'?'Delete <strong>'+e(fullName(patient))+'</strong> and all <strong>'+visits+'</strong> associated assessment(s)?':'Delete the assessment for <strong>'+e(fullName(patient))+'</strong> dated '+fmtDate(assessmentById(id).date)+'?')+' Export a backup first if you need a copy.</p><div class="form-error section-gap" id="delete-error" role="alert"></div><div class="form-actions">'+btn('Cancel','close-modal')+btn('Delete record','confirm-delete','trash','btn-danger','data-store="'+kind+'" data-id="'+e(id)+'"')+'</div>');}
  async function backup(){const snapshot=await DB.snapshot();U.download(new Blob([JSON.stringify(snapshot,null,2)],{type:'application/json'}),'PhilPEN-backup-'+U.today()+'.json');toast('Backup download created. Keep it in a safe location.');}
  async function previewRestore(file){if(!file)return;if(file.size>100*1024*1024)throw new Error('Backup must be smaller than 100 MB.');let parsed;try{parsed=JSON.parse(await file.text());}catch{throw new Error('This is not a valid JSON backup.');}if(parsed.app!=='PhilPEN'||parsed.schemaVersion!==1||!parsed.stores)throw new Error('Choose a PhilPEN version 1 JSON backup.');const counts=['patients','assessments','equipment'].map(k=>[k,Array.isArray(parsed.stores[k])?parsed.stores[k].length:'Invalid']);showModal('Restore database backup',file.name,'<p class="confirm-text">This backup contains '+counts.map(([k,v])=>'<strong>'+e(v)+'</strong> '+k).join(', ')+'. Every record will be validated before anything is saved.</p><form id="restore-form"><div class="form-error section-gap" role="alert"></div><div class="field section-gap"><label for="restore-mode">Restore method</label><select id="restore-mode" name="mode"><option value="merge">Merge — matching IDs are updated; other records stay</option><option value="replace">Replace — erase current records and use the backup</option></select><small>Merge also restores settings included in the backup. Download a current backup first if you need to keep them.</small></div><label class="check-option section-gap"><input type="checkbox" name="confirm" required>I understand this will change the local database.</label>'+formFooter('Validate & restore')+'</form>');document.getElementById('restore-form').addEventListener('submit',async event=>{event.preventDefault();const f=event.currentTarget;if(!f.reportValidity())return;const error=f.querySelector('.form-error'),b=f.querySelector('[type=submit]');error.textContent='';b.disabled=true;try{await DB.restore(parsed,{replace:f.elements.mode.value==='replace'});await refresh();closeModal(true);render();toast('Backup restored successfully.');}catch(err){error.textContent=err.message;}finally{b.disabled=false;}});}
  async function previewCSV(file){if(!file)return;if(file.size>20*1024*1024)throw new Error('CSV must be smaller than 20 MB.');const result=R.parsePatientsCSV(await file.text());const errors=[...(result.errors||[])].map(x=>typeof x==='string'?x:JSON.stringify(x));for(const [i,row] of result.rows.entries()){if(!brgyNames().includes(row.barangay))errors.push('Row '+(i+2)+': choose one of the 40 source barangays.');}const existing=new Set(state.patients.map(p=>p.id));const known=result.rows.filter(r=>r.id&&existing.has(r.id));showModal('Import patient CSV',file.name,'<p class="confirm-text"><strong>'+result.rows.length+'</strong> patient rows found. '+(known.length?'<strong>'+known.length+'</strong> existing IDs will be updated.':'New patients will be added.')+'</p>'+(errors.length?'<div class="form-error section-gap"><strong>Fix these errors before importing:</strong><pre class="import-errors">'+e(errors.slice(0,60).join('\n'))+'</pre></div>':'<div class="notice section-gap">'+icon('check')+'<span>CSV columns were recognized. All rows will be validated together before saving.</span></div>')+'<div class="actions section-gap">'+btn('Download template','csv-template','download','btn-text')+'</div><div class="form-error section-gap" id="csv-error" role="alert"></div><div class="form-actions">'+btn('Cancel','close-modal')+'<button id="confirm-csv" class="btn btn-primary" '+(errors.length||!result.rows.length?'disabled':'')+'>Import '+result.rows.length+' patients</button></div>');document.getElementById('confirm-csv').addEventListener('click',async event=>{event.currentTarget.disabled=true;try{const rows=result.rows.map(r=>({...r,barangay:brgyNames().find(b=>b.toLowerCase()===String(r.barangay).toLowerCase())||r.barangay}));await DB.bulkPut('patients',rows);await refresh();closeModal(true);state.route='patients';location.hash='patients';render();toast(rows.length+' patients imported.');}catch(err){document.getElementById('csv-error').textContent=err.message;event.currentTarget.disabled=false;}});}


  async function previewExcel(file){
    if(!file)return;toast('Reading Excel workbook…');
    const result=await window.PhilExcel.readFile(file);
    const known=new Set(state.patients.map(window.PhilExcel.identity));
    const duplicates=result.patients.filter(p=>known.has(window.PhilExcel.identity(p))).length;
    const monthOnly=result.assessments.filter(a=>a.datePrecision==='month').length;
    showModal('Import Excel masterlist',file.name,
      '<p>Review the recognized records before saving. Existing patients and visits are kept; repeated imports skip matching records.</p><div class="import-summary">'+tag(result.patients.length+' patients','blue')+tag(result.assessments.length+' assessments','blue')+tag(duplicates+' existing patients')+'</div><p class="help-line">'+e(result.sheets.map(s=>s.name+' · '+s.period+' · '+s.rows+' rows').join('; '))+'</p>'+
      (monthOnly?'<div class="notice section-gap">'+icon('info')+'<span>'+monthOnly+' rows have a month only. They use the worksheet month and year, with day 01 for sorting; the exact visit day remains unknown.</span></div>':'')+
      (result.patients.length?'<div class="table-wrap section-gap"><table><thead><tr><th>Patient</th><th>Barangay</th><th>Birth date</th></tr></thead><tbody>'+result.patients.slice(0,8).map(p=>'<tr><td>'+e(fullName(p))+'</td><td>'+e(p.barangay)+'</td><td>'+fmtDate(p.dob)+'</td></tr>').join('')+'</tbody></table></div><p class="help-line">Preview: first '+Math.min(8,result.patients.length)+' patients.</p>':'')+
      (result.errors.length?'<div class="form-error section-gap"><strong>Correct these rows in Excel, then import again:</strong><pre class="import-errors">'+e(result.errors.join('\n'))+'</pre></div>':'')+
      (result.warnings.length?'<details class="import-review section-gap"><summary>'+result.warnings.length+' source notes to review</summary><pre>'+e(result.warnings.join('\n'))+'</pre></details><label class="check-option section-gap"><input type="checkbox" id="excel-review-ack">I reviewed the source notes. Keep the recorded ages and categories.</label>':'')+
      '<div class="form-error section-gap" id="excel-error" role="alert"></div><div class="form-actions">'+btn('Cancel','close-modal')+'<button class="btn btn-primary" id="confirm-excel" '+(result.errors.length||!result.patients.length?'disabled':'')+'>Import records</button></div>');
    document.getElementById('confirm-excel').addEventListener('click',async event=>{const b=event.currentTarget;const error=document.getElementById('excel-error');if(result.warnings.length&&!document.getElementById('excel-review-ack').checked){error.textContent='Review and acknowledge the source notes first.';return;}b.disabled=true;try{const saved=await DB.importRecords(result);await refresh();closeModal(true);location.hash='patients';state.route='patients';render();toast(saved.patients+' patients and '+saved.assessments+' assessments added. '+saved.skippedAssessments+' existing visits skipped.');}catch(err){error.textContent=err.message;b.disabled=false;}});
  }

  async function handleAction(el){const action=el.dataset.action,id=el.dataset.id;switch(action){case 'assessment-columns':jumpAssessmentColumns(el.dataset.group);break;case 'new-patient':openPatient();break;case 'edit-patient':openPatient(id);break;case 'view-patient':viewPatient(id);break;case 'new-assessment':openAssessment(null,id);break;case 'edit-assessment':openAssessment(id);break;case 'edit-equipment':openEquipment(id);break;case 'close-modal':closeModal();break;case 'delete-patient':confirmDelete('patients',id);break;case 'delete-assessment':confirmDelete('assessments',id);break;case 'confirm-delete':el.disabled=true;try{await DB.remove(el.dataset.store,id);await refresh();closeModal(true);render();toast('Record deleted.');}catch(err){document.getElementById('delete-error').textContent=err.message;el.disabled=false;}break;case 'page':state.page=Number(el.dataset.page);if(state.route==='patients')document.getElementById('patient-results').innerHTML=patientTable();else if(state.route==='assessments')refreshAssessmentTable();else if(state.route==='medications')render();break;case 'backup':await backup();break;case 'restore':document.getElementById('restore-input').click();break;case 'import-excel':document.getElementById('excel-input').click();break;case 'import-csv':document.getElementById('csv-input').click();break;case 'csv-template':R.downloadPatientTemplate();break;case 'patients-csv':R.exportPatientsCSV(patientRows());break;case 'encounters-csv':R.exportEncountersCSV(context());break;case 'indicators-csv':R.exportIndicatorsCSV(context());break;case 'export-workbook':el.disabled=true;try{await R.exportWorkbook(context());toast('Excel report downloaded for '+period()+'.');}finally{el.disabled=false;}break;case 'print':window.print();break;}}
  document.addEventListener('click',event=>{const el=event.target.closest('[data-action]');if(el){event.preventDefault();handleAction(el).catch(err=>toast(err.message||'Action could not be completed.','error'));}});
  document.addEventListener('submit',event=>{if(['patient-form','assessment-form','equipment-form','settings-form'].includes(event.target.id)){event.preventDefault();saveForm(event.target);}});
  document.addEventListener('change',event=>{const el=event.target;if(el.dataset.filter){let value=el.value;if(el.dataset.filter==='year'){value=Number(value);if(!Number.isInteger(value)||value<2000||value>2200){toast('Enter a reporting year from 2000 to 2200.','error');el.value=state.filters.year;return;}}state.filters[el.dataset.filter]=value;state.page=1;render();}if(['condition-filter','sex-filter','sort-filter'].includes(el.id)){state[{ 'condition-filter':'condition','sex-filter':'sex','sort-filter':'sort'}[el.id]]=el.value;state.page=1;document.getElementById('patient-results').innerHTML=patientTable();}if(el.closest('#assessment-form')){if(el.name==='patientId'){const f=el.form;if(!patientById(el.value)?.dob)f.elements.age.value='';}updateAssessmentFields(el.name);}if(el.closest('#equipment-form')&&el.name==='equipmentBarangay'){const f=el.form,r=state.equipment.find(x=>x.id===el.value);for(const k of ['manualBP','automaticBP','glucometers','testStrips'])f.elements[k].value=r?r[k]:'';}});
  document.addEventListener('input',event=>{const el=event.target;if(el.closest('dialog form'))modalDirty=true;if(el.id==='patient-search'||el.id==='assessment-search'){state.query=el.value;state.page=1;if(el.id==='patient-search')document.getElementById('patient-results').innerHTML=patientTable();else refreshAssessmentTable();}if(el.id==='equipment-search'){state.query=el.value;const pos=el.selectionStart;render();const replacement=document.getElementById('equipment-search');replacement.focus();replacement.setSelectionRange(pos,pos);}if(el.closest('#assessment-form')&&['weightKg','heightM','date','age'].includes(el.name))updateAssessmentFields(el.name);});
  document.getElementById('restore-input').addEventListener('change',event=>{previewRestore(event.target.files[0]).catch(err=>toast(err.message,'error'));event.target.value='';});
  document.getElementById('excel-input').addEventListener('change',event=>{previewExcel(event.target.files[0]).catch(err=>toast(err.message,'error'));event.target.value='';});
  document.getElementById('csv-input').addEventListener('change',event=>{previewCSV(event.target.files[0]).catch(err=>toast(err.message,'error'));event.target.value='';});
  document.getElementById('menu-toggle').addEventListener('click',()=>document.getElementById('sidebar').classList.toggle('open'));
  modal.addEventListener('cancel',event=>{event.preventDefault();closeModal();});
  window.addEventListener('hashchange',()=>{if(state.ready)route();});
  window.addEventListener('beforeunload',event=>{if(modal.open&&modalDirty){event.preventDefault();event.returnValue='';}});
  async function init(){try{if(!SEED||!DB||!R||!U)throw new Error('An application file is missing. Keep index.html together with the css, js and data folders.');await DB.init(SEED);if(window.PHILPEN_INITIAL_DATA)await DB.importRecords(window.PHILPEN_INITIAL_DATA,{once:'seed-tagpos-2026-09-v1'});await refresh();state.ready=true;document.getElementById('db-status').textContent='Saved locally';route();}catch(err){document.getElementById('db-status').textContent='Storage unavailable';main.innerHTML='<div class="loading-state"><h1>Unable to open the workspace</h1><p>'+e(err.message)+'</p><p class="help-line">Open index.html in a normal Edge or Chrome window. Keep all application folders together and allow local browser storage.</p><button class="btn section-gap" onclick="location.reload()">Try again</button></div>';}}
  init();
})();
